const header = document.getElementById('header');
window.addEventListener('scroll', () => {
if (window.scrollY > 50) {
header.classList.add('scrolled');
} else {
header.classList.remove('scrolled');
}
});
const hamburger = document.getElementById('hamburger');
const mainNav = document.querySelector('.main-nav');
hamburger.addEventListener('click', () => {
mainNav.classList.toggle('open');
});
document.querySelectorAll('.main-nav a').forEach(link => {
link.addEventListener('click', () => {
mainNav.classList.remove('open');
});
});
document.querySelectorAll('a[href^="#"]').forEach(anchor => {
anchor.addEventListener('click', function(e) {
const target = document.querySelector(this.getAttribute('href'));
if (target) {
e.preventDefault();
const headerHeight = header.offsetHeight;
const targetPos = target.getBoundingClientRect().top + window.scrollY - headerHeight;
window.scrollTo({ top: targetPos, behavior: 'smooth' });
}
});
});
document.querySelectorAll('.cf-tab').forEach(tab => {
tab.addEventListener('click', function() {
const targetId = 'tab-' + this.dataset.tab;
const parent = this.closest('.section') || document.body;
parent.querySelectorAll('.cf-tab').forEach(t => t.classList.remove('active'));
parent.querySelectorAll('.cf-tab-content').forEach(c => c.classList.remove('active'));
this.classList.add('active');
const target = document.getElementById(targetId);
if (target) target.classList.add('active');
});
});
const form = document.getElementById('contact-form');
if (form) {
form.addEventListener('submit', function(e) {
e.preventDefault();
const btn = form.querySelector('.btn-submit');
const originalText = btn.textContent;
const isEn = document.documentElement.lang === 'en';
btn.textContent = isEn ? 'Sending...' : 'Invio in corso...';
btn.disabled = true;
const formData = new FormData(form);
formData.append('from_name', form.querySelector('#nome').value + ' ' + form.querySelector('#cognome').value);
fetch('https://api.web3forms.com/submit', {
method: 'POST',
body: formData
})
.then(function(res) { return res.json(); })
.then(function(data) {
if (data.success) {
btn.textContent = isEn ? 'Request sent!' : 'Richiesta inviata!';
btn.style.background = '#1a7a4a';
btn.style.borderColor = '#1a7a4a';
setTimeout(function() {
btn.textContent = originalText;
btn.style.background = '';
btn.style.borderColor = '';
btn.disabled = false;
form.reset();
}, 3000);
} else {
throw new Error(data.message);
}
})
.catch(function(error) {
console.error('Web3Forms error:', error);
btn.textContent = isEn ? 'Error, retry' : 'Errore, riprova';
btn.style.background = '#c0392b';
btn.style.borderColor = '#c0392b';
setTimeout(function() {
btn.textContent = originalText;
btn.style.background = '';
btn.style.borderColor = '';
btn.disabled = false;
}, 3000);
});
});
}